<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import type {Session} from '../FleetAndDocuments/contracts';
import {registrationDate} from '../FleetAndDocuments/presentation';
import {all,request,failure} from '../Administration/api';
import SearchSelect from '../Workshop/components/SearchSelect.vue';
import {modules,links,parseAudit,parseDetail} from './contracts';
import type {AuditPage,AuditDetail,AuditEvent} from './contracts';
const props=defineProps<{session:Session|null}>(),emit=defineEmits<{denied:[error:unknown]}>();
const allowed=computed(()=>props.session?.roles.includes('administrator')??false);
const from=ref(''),to=ref(''),actor=ref(''),module=ref(''),operation=ref(''),busy=ref(false),error=ref(''),lookupError=ref(''),fields=ref<Record<string,string[]>>({});
const result=ref<AuditPage|null>(null),detail=ref<AuditDetail|null>(null),users=ref<{value:string;label:string}[]>([]);let generation=0,sessionGeneration=0;
const keys=computed(()=>[...new Set([...Object.keys(detail.value?.before??{}),...Object.keys(detail.value?.after??{})])]);
function problem(e:unknown):void {const p=failure(e);error.value=p.message;fields.value=p.fields;if([401,403,419].includes(p.status))emit('denied',p);}
async function lookup():Promise<void>{const current=sessionGeneration;try{const data=await all<{id:number;name:string}>('/users');if(current===sessionGeneration)users.value=data.map(u=>({value:String(u.id),label:u.name}));}catch(e){if(current!==sessionGeneration)return;lookupError.value='No se pudo cargar el selector de usuarios. Vuelve a consultar.';if([401,403,419].includes(failure(e).status))problem(e);}}
async function consult(page=1):Promise<void>{if(busy.value||!allowed.value)return;const current=++generation;busy.value=true;error.value='';fields.value={};result.value=null;detail.value=null;const q=new URLSearchParams({page:String(page),per_page:'25'});for(const[k,v]of Object.entries({from:from.value,to:to.value,actor_id:actor.value,module:module.value,operation:operation.value}))if(v)q.set(k,v);try{const data=parseAudit(await request<unknown>(`/audit?${q}`));if(current===generation)result.value=data;}catch(e){if(current===generation)problem(e);}finally{if(current===generation)busy.value=false;}}
async function show(row:AuditEvent):Promise<void>{if(busy.value||!allowed.value)return;const current=++generation;busy.value=true;error.value='';detail.value=null;try{const data=parseDetail(await request<unknown>(`/audit/${row.source}/${row.id}`));if(data.event.id!==row.id||data.event.source!==row.source)throw new Error('Detalle incompatible.');if(current===generation)detail.value=data;}catch(e){if(current===generation)problem(e);}finally{if(current===generation)busy.value=false;}}
watch(()=>props.session?`${props.session.id}:${props.session.roles.join('|')}`:'',()=>{generation++;sessionGeneration++;result.value=null;detail.value=null;users.value=[];busy.value=false;error.value='';lookupError.value='';if(allowed.value)void lookup();},{immediate:true});
onBeforeUnmount(()=>{generation++;sessionGeneration++;});
</script>
<template><section v-if="allowed" class="space-y-5"><p class="notice-info">Solo lectura de historiales existentes. No es una bitácora completa de todas las ediciones: algunas operaciones de catálogos no conservan actor ni cambios. Las fechas corresponden al registro en America/Costa_Rica; el nombre del actor es el actual.</p><form class="panel grid gap-4 sm:grid-cols-2 lg:grid-cols-3" @submit.prevent="consult()"><label>Desde<input v-model="from" type="date" class="field" :disabled="busy"></label><label>Hasta<input v-model="to" type="date" :min="from||undefined" class="field" :disabled="busy"></label><SearchSelect v-model="actor" label="Usuario" :options="users" :disabled="busy"/><label>Módulo<select aria-label="Módulo" v-model="module" class="field" :disabled="busy"><option value="">Todos</option><option v-for="(name,key) in modules" :key="key" :value="key">{{name}}</option></select></label><label>Tipo de operación<input v-model="operation" class="field" placeholder="Código exacto mostrado en la tabla" maxlength="100" :disabled="busy"></label><button class="btn-primary self-end" :disabled="busy">Consultar auditoría</button></form><p v-if="lookupError" role="alert" class="notice-error">{{lookupError}}</p><p v-if="busy" role="status">Consultando auditoría…</p><div v-if="error" role="alert" class="notice-error"><p>{{error}}</p><p v-for="(messages,key) in fields" :key="key">{{key}}: {{messages.join(' ')}}</p></div><section v-if="result" class="panel space-y-4"><p>{{result.meta.total}} operaciones encontradas</p><p v-if="!result.rows.length" role="status">Sin operaciones para estos filtros.</p><div v-else class="overflow-x-auto"><table class="data-table"><caption class="sr-only">Operaciones administrativas</caption><thead><tr><th>Fecha y hora</th><th>Actor</th><th>Módulo</th><th>Operación</th><th>Registro afectado</th><th>Consulta</th></tr></thead><tbody><tr v-for="row in result.rows" :key="row.source+row.id"><td>{{registrationDate(row.registered_at)}}</td><td>{{row.actor_name}} · ID {{row.actor_id}}</td><td>{{modules[row.module]}}</td><td><code>{{row.operation}}</code></td><td class="break-all">{{row.record_type}} · {{row.record_id}}</td><td><button class="btn-secondary" :disabled="busy" @click="show(row)" :aria-label="`Ver detalle ${row.id}`">Ver detalle</button></td></tr></tbody></table></div><nav aria-label="Paginación de auditoría" class="flex gap-3 items-center"><button class="btn-secondary" :disabled="busy||result.meta.current_page<=1" @click="consult(result.meta.current_page-1)">Anterior</button><span>Página {{result.meta.current_page}} de {{result.meta.last_page}}</span><button class="btn-secondary" :disabled="busy||result.meta.current_page>=result.meta.last_page" @click="consult(result.meta.current_page+1)">Siguiente</button></nav></section><section v-if="detail" class="panel space-y-4" aria-label="Detalle de auditoría"><h2 class="font-semibold text-xl">Detalle de operación</h2><p>{{detail.event.operation}} · {{detail.event.id}}</p><p>{{detail.event.actor_name}} · {{registrationDate(detail.event.registered_at)}}</p><p class="break-all">Registro: {{detail.event.record_type}} · {{detail.event.record_id}}</p><div v-if="keys.length" class="overflow-x-auto"><table class="data-table"><caption class="sr-only">Cambios registrados</caption><thead><tr><th>Campo</th><th>Anterior</th><th>Posterior</th></tr></thead><tbody><tr v-for="key in keys" :key="key"><td>{{key}}</td><td>{{detail.before&&Object.hasOwn(detail.before,key)?String(detail.before[key]??'Sin valor'):'No registrado'}}</td><td>{{detail.after&&Object.hasOwn(detail.after,key)?String(detail.after[key]??'Sin valor'):'No registrado'}}</td></tr></tbody></table></div><p v-else>No hay cambios anteriores y posteriores seguros disponibles para esta operación.</p><a :href="links[detail.event.module]" class="text-blue-700 underline">Abrir módulo original</a><p class="text-sm text-slate-600">El enlace abre la vista existente del módulo; utiliza el identificador del registro para localizarlo. Los textos libres y datos privados se omiten.</p></section></section></template>
